// Open-flow board test (Basys2-250): the logic analyzer's link (#3176), the JTAG's user access primitive BSCAN_SPARTAN3.
//   led[7:0]  the top byte of a 24-bit counter on the 50 MHz clock (about 3 changes a second on LD0)
//   the capture core (silinx_capture.v, generated by core/ila.js) samples the counter's low 16 bits on clk, 1024 samples,
//   64 before the trigger (the count 1000); the PC reads it over the JTAG cable through USER1 (DRCK1, SEL1, CAPTURE,
//   SHIFT, TDI, TDO1; TDO2 tied low)
module top (
    input  wire       clk,
    output wire [7:0] led
);
  reg [23:0] n = 0;
  always @(posedge clk) n <= n + 1;
  assign led = n[23:16];
  wire tck, sel, capture, shift, tdi, tdo;
  BSCAN_SPARTAN3 silinx_bscan (.DRCK1(tck), .SEL1(sel), .CAPTURE(capture), .SHIFT(shift), .TDI(tdi), .TDO1(tdo), .TDO2(1'b0));
  silinx_capture silinx_ila (.clk(clk), .probe(n[15:0]), .tck(tck), .sel(sel), .capture(capture), .shift(shift), .tdi(tdi), .tdo(tdo));
endmodule
